  1	<!DOCTYPE html>
  2	<html lang="en">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Todos</title>
  7	<style>
  8	  * { box-sizing: border-box; }
  9	  body {
 10	    margin: 0;
 11	    padding: 40px 16px;
 12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
 13	    background: #f5f5f4;
 14	    color: #1c1917;
 15	  }
 16	  main { max-width: 520px; margin: 0 auto; }
 17	  h1 { font-size: 28px; margin: 0 0 16px; }
 18	  form { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
 19	  input[type="text"] {
 20	    flex: 1;
 21	    min-width: 0;
 22	    padding: 10px 12px;
 23	    font: inherit;
 24	    border: 1px solid #d6d3d1;
 25	    border-radius: 8px;
 26	    background: #fff;
 27	  }
 28	  input[type="date"] {
 29	    padding: 10px 12px;
 30	    font: inherit;
 31	    border: 1px solid #d6d3d1;
 32	    border-radius: 8px;
 33	    background: #fff;
 34	    color: inherit;
 35	  }
 36	  input[type="text"]:focus, input[type="date"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
 37	  button {
 38	    font: inherit;
 39	    border: 0;
 40	    border-radius: 8px;
 41	    cursor: pointer;
 42	  }
 43	  .add { padding: 10px 18px; background: #2563eb; color: #fff; }
 44	  .add:hover { background: #1d4ed8; }
 45	  ul { list-style: none; margin: 0; padding: 0; }
 46	  li {
 47	    display: flex;
 48	    align-items: center;
 49	    gap: 12px;
 50	    padding: 10px 12px;
 51	    margin-bottom: 8px;
 52	    background: #fff;
 53	    border: 1px solid #e7e5e4;
 54	    border-radius: 8px;
 55	  }
 56	  .text { flex: 1; overflow-wrap: anywhere; }
 57	  li input[type="checkbox"] { width: 18px; height: 18px; margin: 0; cursor: pointer; accent-color: #2563eb; }
 58	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
 59	  .due { font-size: 14px; color: #57534e; white-space: nowrap; }
 60	  li[data-overdue="true"] { border-color: #fca5a5; box-shadow: inset 3px 0 0 #dc2626; }
 61	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
 62	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
 63	  .filters button { padding: 6px 12px; background: transparent; color: #44403c; border: 1px solid #d6d3d1; }
 64	  .filters button:hover { background: #e7e5e4; }
 65	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
 66	  .delete { padding: 6px 10px; background: transparent; color: #b91c1c; }
 67	  .delete:hover { background: #fee2e2; }
 68	  .empty { color: #78716c; text-align: center; padding: 16px 0; }
 69	</style>
 70	</head>
 71	<body>
 72	<main>
 73	  <h1>Todos</h1>
 74	  <form id="todo-form">
 75	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
 76	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
 77	    <button type="submit" class="add" data-testid="todo-add">Add</button>
 78	  </form>
 79	  <div class="filters" role="group" aria-label="Filter todos">
 80	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
 81	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
 82	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
 83	  </div>
 84	  <ul data-testid="todo-list"></ul>
 85	  <p class="empty" hidden>No todos yet.</p>
 86	</main>
 87	<script>
 88	(function () {
 89	  var STORAGE_KEY = 'todos';
 90	  var form = document.getElementById('todo-form');
 91	  var input = document.querySelector('[data-testid="todo-input"]');
 92	  var dueInput = document.querySelector('[data-testid="todo-due"]');
 93	  var list = document.querySelector('[data-testid="todo-list"]');
 94	  var empty = document.querySelector('.empty');
 95	  var filterButtons = document.querySelectorAll('[data-filter]');
 96	
 97	  function load() {
 98	    try {
 99	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
100	      return Array.isArray(data) ? data : [];
101	    } catch (e) {
102	      return [];
103	    }
104	  }
105	
106	  function save() {
107	    try {
108	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
109	    } catch (e) {
110	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
111	    }
112	  }
113	
114	  function makeId() {
115	    if (window.crypto && typeof crypto.randomUUID === 'function') {
116	      return crypto.randomUUID();
117	    }
118	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
119	  }
120	
121	  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
122	  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
123	  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
124	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
125	
126	  function pad(n) { return (n < 10 ? '0' : '') + n; }
127	
128	  function todayLocal() {
129	    var d = new Date();
130	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
131	  }
132	
133	  // Overdue: due date strictly before today's local date. Due today is never overdue.
134	  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
135	  function isOverdue(todo, today) {
136	    return !!todo.due && todo.due < today;
137	  }
138	
139	  function formatDue(due) {
140	    var parts = due.split('-');
141	    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
142	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
143	  }
144	
145	  var todos = load();
146	  var filter = 'all';
147	  var renderedDay = null;
148	
149	  // Ordering rule (project decision): active todos first, completed todos below.
150	  // Within each group, keep insertion order (oldest first). `todos` is stored
151	  // in insertion order, so splitting it into two groups preserves that.
152	  function visibleTodos() {
153	    var active = todos.filter(function (t) { return !t.completed; });
154	    var completed = todos.filter(function (t) { return t.completed; });
155	    if (filter === 'active') return active;
156	    if (filter === 'completed') return completed;
157	    return active.concat(completed);
158	  }
159	
160	  function render() {
161	    list.textContent = '';
162	    var visible = visibleTodos();
163	    var today = todayLocal();
164	    renderedDay = today;
165	    visible.forEach(function (todo) {
166	      var li = document.createElement('li');
167	      li.setAttribute('data-testid', 'todo-item');
168	      li.setAttribute('data-id', todo.id);
169	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
170	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
171	
172	      var toggle = document.createElement('input');
173	      toggle.type = 'checkbox';
174	      toggle.checked = !!todo.completed;
175	      toggle.setAttribute('data-testid', 'todo-toggle');
176	      toggle.setAttribute('aria-label', 'Mark complete');
177	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
178	
179	      var text = document.createElement('span');
180	      text.className = 'text';
181	      text.setAttribute('data-testid', 'todo-text');
182	      text.textContent = todo.text;
183	
184	      var del = document.createElement('button');
185	      del.type = 'button';
186	      del.className = 'delete';
187	      del.setAttribute('data-testid', 'todo-delete');
188	      del.setAttribute('aria-label', 'Delete todo');
189	      del.textContent = 'Delete';
190	      del.addEventListener('click', function () { remove(todo.id); });
191	
192	      li.appendChild(toggle);
193	      li.appendChild(text);
194	      if (todo.due) {
195	        var due = document.createElement('time');
196	        due.className = 'due';
197	        due.setAttribute('data-testid', 'todo-due-date');
198	        due.setAttribute('datetime', todo.due);
199	        due.textContent = 'Due ' + formatDue(todo.due);
200	        li.appendChild(due);
201	      }
202	      li.appendChild(del);
203	      list.appendChild(li);
204	    });
205	    empty.textContent = todos.length === 0 ? 'No todos yet.'
206	      : filter === 'active' ? 'No active todos.'
207	      : 'No completed todos.';
208	    empty.hidden = visible.length > 0;
209	    filterButtons.forEach(function (btn) {
210	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
211	    });
212	  }
213	
214	  function add(text, due) {
215	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due });
216	    save();
217	    render();
218	  }
219	
220	  function remove(id) {
221	    todos = todos.filter(function (t) { return t.id !== id; });
222	    save();
223	    render();
224	  }
225	
226	  function setCompleted(id, completed) {
227	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
228	    save();
229	    render();
230	  }
231	
232	  filterButtons.forEach(function (btn) {
233	    btn.addEventListener('click', function () {
234	      filter = btn.getAttribute('data-filter');
235	      render();
236	    });
237	  });
238	
239	  form.addEventListener('submit', function (e) {
240	    e.preventDefault();
241	    var text = input.value.trim();
242	    if (!text) return;
243	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
244	    add(text, due);
245	    input.value = '';
246	    dueInput.value = '';
247	    input.focus();
248	  });
249	
250	  render();
251	
252	  // Overdue status changes at local midnight; re-render when the day rolls over.
253	  setInterval(function () {
254	    if (todayLocal() !== renderedDay) render();
255	  }, 30000);
256	})();
257	</script>
258	</body>
259	</html>

