p='index.html'; s=open(p).read()
def r(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
r('''  input[type="date"] {
    padding''','''  input[type="date"], select {
    padding''')
r('''  input[type="text"]:focus, input[type="date"]:focus {''','''  input[type="text"]:focus, input[type="date"]:focus, select:focus {''')
r('''  li[data-overdue="true"] { border-color: #fca5a5; box-shadow: inset 3px 0 0 #dc2626; }
''','''  /* Priority owns the row colour: a left stripe and a light tint. */
  li[data-priority="high"] { background: #fef2f2; border-color: #fecaca; box-shadow: inset 4px 0 0 #dc2626; }
  li[data-priority="med"] { background: #fffbeb; border-color: #fde68a; box-shadow: inset 4px 0 0 #d97706; }
  li[data-priority="low"] { background: #fafaf9; border-color: #e7e5e4; box-shadow: inset 4px 0 0 #a8a29e; }
  .priority { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; padding: 2px 6px; border-radius: 4px; white-space: nowrap; }
  li[data-priority="high"] .priority { background: #fee2e2; color: #b91c1c; }
  li[data-priority="med"] .priority { background: #fef3c7; color: #b45309; }
  li[data-priority="low"] .priority { background: #e7e5e4; color: #57534e; }
